methods:
@Builder
  private searchBar() {
    Row({ space: TOK_SPACE_CONTROL_INLINE }) {
      Stack({ alignContent: Alignment.Center }) {
        Image((this.appThemeScheme === 'night' ? $r('app.media.search_back_theme_night') : $r('app.media.search_back'))).width(20).height(20);
      }
      .width(32)
      .height(32)
      .borderRadius(16)
      .onClick((): void => this.onBack());

      Row() {
        ReaderSearchField({
          variant: 'bookPage',
          mode: 'submit',
          focusOnAppear: this.focusInputOnAppear,
          text: this.keyword,
          placeholder: '搜索书名、作者...',
          accessibilityLabel: '搜索书名或作者',
          isTablet: this.isTablet,
          clearable: true,
          submitEnabled: this.presentation.kind !== 'loading',
          onTextChange: (value: string): void => {
            this.keyword = value;
            this.viewState.keywordDraft = value;
          },
          onSubmit: (): void => this.submitSearch(),
        });
      }
      .layoutWeight(1)
      .height(this.isTablet ? 40 : 36)
      .alignItems(VerticalAlign.Center);

      // The search action doubles as the ACQ-02 stop control: while a sweep
      // is live the pill reads 停止 and stops the sweep; otherwise it submits.
      // Loading additionally inlines a 13px spinner and submitSearch prevents
      // re-entry.
      Stack({ alignContent: Alignment.Center }) {
        if (this.isSweeping()) {
          Row({ space: 6 }) {
            SearchSpinner({ active: this.isSweeping(), runKey: this.spinnerRunKey,
              reduceMotion: this.reduceMotion, diameter: 13, light: true });
            Text('停止')
              .fontFamily(TYPE_SEARCH_FIELD_ACTION.fontFamily)
              .fontWeight(TYPE_SEARCH_FIELD_ACTION.fontWeight)
              .fontSize(this.isTablet ? TYPE_SEARCH_FIELD_ACTION_WIDE.fontSizeFp : TYPE_SEARCH_FIELD_ACTION.fontSizeFp)
              .lineHeight(this.isTablet ? TYPE_SEARCH_FIELD_ACTION_WIDE.lineHeightFp as number : TYPE_SEARCH_FIELD_ACTION.lineHeightFp as number)
              .fontColor(readerAppColor('TOK_ON_PRIMARY', this.appThemeScheme));
          }
          .alignItems(VerticalAlign.Center);
        } else {
          Text('搜索')
            .fontFamily(TYPE_SEARCH_FIELD_ACTION.fontFamily)
            .fontWeight(TYPE_SEARCH_FIELD_ACTION.fontWeight)
            .fontSize(this.isTablet ? TYPE_SEARCH_FIELD_ACTION_WIDE.fontSizeFp : TYPE_SEARCH_FIELD_ACTION.fontSizeFp)
            .lineHeight(this.isTablet ? TYPE_SEARCH_FIELD_ACTION_WIDE.lineHeightFp as number : TYPE_SEARCH_FIELD_ACTION.lineHeightFp as number)
            .fontColor(readerAppColor('TOK_ON_PRIMARY', this.appThemeScheme));
        }
      }
      .height(this.isTablet ? 40 : 36)
      .padding({ left: this.isTablet ? 18 : TOK_SPACE_CARD_PADDING, right: this.isTablet ? 18 : TOK_SPACE_CARD_PADDING })
      .backgroundColor(readerAppColor('app.action.fill', this.appThemeScheme))
      .opacity(this.canSubmit() ? 1 : 0.4)
      .borderRadius(999)
      .onClick((): void => {
        if (this.isSweeping()) {
          this.onStop();
          return;
        }
        this.submitSearch();
      });
    }
    .width(this.contentFrame().width)
    .height(this.isTablet ? 56 : 52)
    .padding({ left: this.isTablet ? 20 : TOK_SPACE_MD, right: this.isTablet ? 20 : TOK_SPACE_MD, top: TOK_SPACE_XS })
    .alignItems(VerticalAlign.Center)
    .hitTestBehavior(HitTestMode.Transparent);
  }

@Builder
  private initialContent() {
    Column({ space: 0 }) {
      if (this.presentation.kind === 'initial' || this.presentation.kind === 'sourceRequired' ||
        this.presentation.kind === 'sourceLoadError') {
        if (this.presentation.historyStatus === 'loading') {
          Text('正在读取搜索历史')
            .fontFamily(TYPE_SEARCH_HISTORY_STATUS.fontFamily as string).fontSize(TYPE_SEARCH_HISTORY_STATUS.fontSizeFp).lineHeight(TYPE_SEARCH_HISTORY_STATUS.lineHeightFp as number)
            .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme));
        } else if (this.presentation.historyStatus === 'loadFailed' || this.presentation.historyStatus === 'clearFailed') {
          Column({ space: TOK_SPACE_XS }) {
            Text(this.presentation.historyStatus === 'clearFailed' ? '搜索历史清空失败' : '搜索历史读取失败')
              .fontFamily(TYPE_SEARCH_HISTORY_STATUS.fontFamily as string).fontSize(TYPE_SEARCH_HISTORY_STATUS.fontSizeFp).lineHeight(TYPE_SEARCH_HISTORY_STATUS.lineHeightFp as number)
              .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme));
            this.secondaryPill(this.presentation.historyStatus === 'clearFailed' ? '重试清空' : '重试读取',
              (): void => this.onRetryHistory());
          }.width('100%').padding({ bottom: TOK_SPACE_XS });
        }
      }
      if ((this.presentation.kind === 'initial' || this.presentation.kind === 'sourceRequired' ||
        this.presentation.kind === 'sourceLoadError') && this.presentation.history.length > 0) {
        Row() {
          Text('最近搜索')
            .fontFamily(TYPE_SEARCH_HISTORY_HEADING.fontFamily)
            .fontWeight(TYPE_SEARCH_HISTORY_HEADING.fontWeight)
            .fontSize(TYPE_SEARCH_HISTORY_HEADING.fontSizeFp)
            .lineHeight(TYPE_SEARCH_HISTORY_HEADING.lineHeightFp as number)
            .fontColor(readerAppColor('TOK_INK', this.appThemeScheme))
            .layoutWeight(1);
          Text('清空记录')
            .fontFamily(TYPE_APP_FILTER_OPTION.fontFamily)
            .fontWeight(TYPE_APP_FILTER_OPTION.fontWeight)
            .fontSize(TYPE_APP_FILTER_OPTION.fontSizeFp)
            .lineHeight(TYPE_APP_FILTER_OPTION.lineHeightFp as number)
            .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
            .enabled(this.presentation.historyStatus !== 'loading')
            .onClick((): void => this.onClearHistory());
        }
        .width('100%')
        .height(26)
        .alignItems(VerticalAlign.Center);

        // All retained history is visible inside the existing page Scroll.
        Flex({ wrap: FlexWrap.Wrap, direction: FlexDirection.Row }) {
          ForEach(this.presentation.history, (keyword: string) => {
            Text(keyword)
              .fontFamily(TYPE_SEARCH_HISTORY_KEYWORD.fontFamily)
              .fontWeight(TYPE_SEARCH_HISTORY_KEYWORD.fontWeight)
              .fontSize(TYPE_SEARCH_HISTORY_KEYWORD.fontSizeFp)
              .lineHeight(TYPE_SEARCH_HISTORY_KEYWORD.lineHeightFp as number)
              .fontColor(readerAppColor('TOK_INK', this.appThemeScheme))
              .padding({ left: 14.5, right: 14.5, top: 7.5, bottom: 7.5 })
              .backgroundColor(readerAppColor('TOK_CARD_BG', this.appThemeScheme))
              .border({ width: TOK_BORDER_W, color: readerAppColor('TOK_BORDER', this.appThemeScheme) })
              .borderRadius(999)
              .maxLines(1).textOverflow({ overflow: TextOverflow.Ellipsis })
              .constraintSize({ maxWidth: this.historyWidth > 0 ? Math.max(0, this.historyWidth - TOK_SPACE_XS) : '100%' })
              .margin({ right: TOK_SPACE_XS, bottom: TOK_SPACE_XS })
              .onClick((): void => {
                this.keyword = keyword;
                this.submitSearch();
              });
          }, (keyword: string): string => `search-history-${keyword}`);
        }
        .width('100%')
        .padding({ top: TOK_SPACE_CARD_PADDING });

      }
    }
    .width('100%')
    .padding({
      left: this.isTablet ? 20 : 18,
      right: this.isTablet ? 20 : 18,
      top: TOK_SPACE_XS,
      bottom: this.searchBottomInset(),
    })
    // Only constrain long chip width; history admission never depends on measurement.
    .onAreaChange((_old: Area, next: Area): void => {
      const outerWidth = Number(next.width);
      if (!Number.isFinite(outerWidth)) return;
      const width = Math.max(0, outerWidth - (this.isTablet ? 40 : 36));
      if (Math.abs(width - this.historyWidth) > .1) {
        this.historyWidth = width;
      }
    });
  }

@Builder
  private resultsContent() {
    Stack({ alignContent: Alignment.Bottom }) {
      Stack({ alignContent: Alignment.TopStart }) {
        Row() {
          Text('找到 ')
            .fontFamily(TYPE_SEARCH_PROGRESS_META.fontFamily)
            .fontWeight(TYPE_SEARCH_PROGRESS_META.fontWeight)
            .fontSize(TYPE_SEARCH_PROGRESS_META.fontSizeFp)
            .lineHeight(TYPE_SEARCH_PROGRESS_META.lineHeightFp as number)
            .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme));
          Text(`${this.visibleGroups.length}`)
            .fontFamily(TYPE_SEARCH_RESULT_COUNT.fontFamily)
            .fontWeight(TYPE_SEARCH_RESULT_COUNT.fontWeight)
            .fontSize(TYPE_SEARCH_RESULT_COUNT.fontSizeFp)
            .lineHeight(TYPE_SEARCH_RESULT_COUNT.lineHeightFp as number)
            .fontColor(readerAppColor('TOK_GREEN', this.appThemeScheme));
          Text(' 本相关书籍')
            .fontFamily(TYPE_SEARCH_PROGRESS_META.fontFamily)
            .fontWeight(TYPE_SEARCH_PROGRESS_META.fontWeight)
            .fontSize(TYPE_SEARCH_PROGRESS_META.fontSizeFp)
            .lineHeight(TYPE_SEARCH_PROGRESS_META.lineHeightFp as number)
            .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme));
          // Reads the presentation directly (not a builder param) so the
          // minimal-update re-render tracks it exactly like the search/stop
          // pill does: the sweep counter must update live per source landing.
          if (this.presentation.kind === 'results') {
            if (this.presentation.localSearchFailed || this.presentation.sourceListFailed) {
              Text(this.partialSearchFailure()).fontSize(TYPE_APP_INHERITED_BODY.fontSizeFp).fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
                .onClick((): void => this.retryOperation());
            }
            if (this.operation()?.fact === 'cancelled' || this.presentation.stopped === true) {
              // ACQ-02: a stopped sweep keeps its partial results; the header
              // states how far the interrupted sweep got so partials never read
              // as a complete verdict.
              Text(` · 已停止,已搜索 ${this.presentation.completedSourceCount}/${this.presentation.totalSourceCount} 个书源`)
                .fontFamily(TYPE_SEARCH_PROGRESS_META.fontFamily)
                .fontWeight(TYPE_SEARCH_PROGRESS_META.fontWeight)
                .fontSize(TYPE_SEARCH_PROGRESS_META.fontSizeFp)
                .lineHeight(TYPE_SEARCH_PROGRESS_META.lineHeightFp as number)
                .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
                .maxLines(1)
                .textOverflow({ overflow: TextOverflow.Ellipsis });
            } else if (this.isSweeping()) {
              Text(` · 正在搜索 ${this.presentation.completedSourceCount}/${this.presentation.totalSourceCount} 个书源,已返回 ${this.visibleGroups.length} 个`)
                .fontFamily(TYPE_SEARCH_PROGRESS_META.fontFamily)
                .fontWeight(TYPE_SEARCH_PROGRESS_META.fontWeight)
                .fontSize(TYPE_SEARCH_PROGRESS_META.fontSizeFp)
                .lineHeight(TYPE_SEARCH_PROGRESS_META.lineHeightFp as number)
                .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
                .maxLines(1)
                .textOverflow({ overflow: TextOverflow.Ellipsis });
            }
            if (this.presentation.failedSourceCount > 0) {
              Text(` · 失败 ${this.presentation.failedSourceCount} 个书源${!this.presentation.searching || this.presentation.completedSourceCount === this.presentation.totalSourceCount ? '，重试' : ''}`)
                .fontFamily(TYPE_SEARCH_PROGRESS_META.fontFamily)
                .fontWeight(TYPE_SEARCH_PROGRESS_META.fontWeight)
                .fontSize(TYPE_SEARCH_PROGRESS_META.fontSizeFp)
                .lineHeight(TYPE_SEARCH_PROGRESS_META.lineHeightFp as number)
                .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
                .maxLines(1)
                .textOverflow({ overflow: TextOverflow.Ellipsis })
                .onClick((): void => this.retryOperation());
            }
          }
        }
        .width(this.contentFrame().width)
        .padding({ left: this.isTablet ? 20 : 18, right: this.isTablet ? 20 : 18, top: 6, bottom: 6 })
        .alignItems(VerticalAlign.Center)
        .position({ x: 0, y: this.searchHeaderHeight() })
        .zIndex(1)
        .hitTestBehavior(HitTestMode.Transparent)
        .onAreaChange((_old: Area, next: Area): void => {
          const height = Number(next.height);
          if (Number.isFinite(height) && height > 0 && Math.abs(height - this.resultStatsHeight) > .1) {
            this.resultStatsHeight = height;
          }
        });

        List({ scroller: this.resultScroller }) {
          LazyForEach(this.resultDataSource, (group: SearchBookGroup) => {
            ListItem() {
              SearchResultCard({ group, isTablet: this.isTablet, cardWidth: this.contentFrame().width,
                onSelectResult: (book: SearchBook, variants: SearchBook[]): void => this.onSelectResult(book, variants) });
            }
          }, (group: SearchBookGroup): string =>
            this.resultGroupKey(group.book));
        }
        .width('100%')
        .height('100%')
        .contentStartOffset(this.searchHeaderHeight() + this.resultStatsHeight)
        .contentEndOffset(this.searchBottomInset())
        .scrollBar(BarState.Off)
        .maintainVisibleContentPosition(true)
        .onTouch((event: TouchEvent): void => {
          if (event.type === TouchType.Down) { this.userInteracting = true; this.cancelScrollRestoreForUser(); }
          else if (event.type === TouchType.Up || event.type === TouchType.Cancel) this.userInteracting = false;
        })
        .onScrollStart((): void => { if (this.userInteracting) this.userScrolling = true; })
        .onScrollStop((): void => { this.userScrolling = false; })
        .onScrollIndex((start: number, end: number): void => this.onResultScrollIndex(start, end))
        .onScroll((): void => { if (this.scrollRestored) this.saveScrollAnchor(); })
        .onAppear((): void => { this.listMounted = true; this.scheduleScrollRestore(); })
        .onDisAppear((): void => { this.listMounted = false; this.restoreEpoch += 1; })
        .onAreaChange((): void => { if (!this.scrollRestored) this.scheduleScrollRestore(); });
      }
      .width('100%')
      .height('100%');

    }
    .width('100%')
    .height('100%');
  }

@Builder
  private emptyContent(keyword: string, searchedSourceCount: number) {
    Scroll() {
      Column({ space: 0 }) {
        Image((this.appThemeScheme === 'night' ? $r('app.media.search_empty_theme_night') : $r('app.media.search_empty')))
          .width(128)
          .height(120)
          .alignSelf(ItemAlign.Center);

        Text('没有找到相关书籍')
          .margin({ top: 28 })
          .fontFamily(TYPE_SEARCH_STATE_TITLE.fontFamily)
          .fontWeight(TYPE_SEARCH_STATE_TITLE.fontWeight)
          .fontSize(TYPE_SEARCH_STATE_TITLE.fontSizeFp)
          .lineHeight(TYPE_SEARCH_STATE_TITLE.lineHeightFp as number)
          .fontColor(readerAppColor('TOK_INK', this.appThemeScheme))
          .textAlign(TextAlign.Center);

        Text(this.isStoppedEmpty()
          ? (searchedSourceCount > 0
            ? `已搜索 ${searchedSourceCount} 个书源后停止,未找到「${keyword}」的相关结果`
            : `已停止搜索,未找到「${keyword}」的相关结果`)
          : `已搜索 ${searchedSourceCount} 个书源,未找到「${keyword}」的相关结果`)
          .margin({ top: TOK_SPACE_CONTROL_INLINE })
          .width('100%')
          .fontFamily(TYPE_SEARCH_STATE_DESCRIPTION.fontFamily)
          .fontWeight(TYPE_SEARCH_STATE_DESCRIPTION.fontWeight)
          .fontSize(TYPE_SEARCH_STATE_DESCRIPTION.fontSizeFp)
          .lineHeight(TYPE_SEARCH_STATE_DESCRIPTION.lineHeightFp as number)
          .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
          .textAlign(TextAlign.Center)
          .maxLines(3);

        if (this.partialSearchFailure().length > 0) {
          Text(this.partialSearchFailure())
            .fontSize(TYPE_APP_INHERITED_BODY.fontSizeFp)
            .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
            .margin({ top: TOK_SPACE_CONTROL_INLINE })
            .onClick((): void => this.retryOperation());
        }

        Column({ space: 0 }) {
          Text('搜索建议')
            .width('100%')
            .fontFamily(TYPE_SEARCH_SUGGESTION_HEADING.fontFamily)
            .fontWeight(TYPE_SEARCH_SUGGESTION_HEADING.fontWeight)
            .fontSize(TYPE_SEARCH_SUGGESTION_HEADING.fontSizeFp)
            .lineHeight(TYPE_SEARCH_SUGGESTION_HEADING.lineHeightFp as number)
            .fontColor(readerAppColor('TOK_INK', this.appThemeScheme))
            .maxLines(1);
          this.suggestion('检查书名拼写是否正确');
          this.suggestion('尝试更短的关键词或作者名');
          this.suggestion('前往书源管理添加或启用更多书源');
        }
        .width(this.isTablet ? 300 : 190)
        .padding({ left: 18.5, right: 18.5, top: 14.5, bottom: 14.5 })
        .margin({ top: 22 })
        .backgroundColor(readerAppColor('TOK_CARD_BG', this.appThemeScheme))
        .border({ width: TOK_BORDER_W, color: readerAppColor('TOK_BORDER', this.appThemeScheme) })
        .borderRadius(12)
        .alignItems(HorizontalAlign.Start)
        .alignSelf(ItemAlign.Center);

        Row({ space: TOK_SPACE_CONTROL_INLINE }) {
          this.primaryPill('添加更多书源', (): void => this.onManageSources());
          this.secondaryPill('重新搜索', (): void => this.retryOperation());
        }
        .margin({ top: 20 })
        .alignSelf(ItemAlign.Center);
      }
      .width('100%')
      .padding({ top: this.searchHeaderHeight() + 50, bottom: this.searchBottomInset(40) });
    }
    .width('100%')
    .height('100%')
    .scrollBar(BarState.Off);
  }

@Builder
  private errorContent(searchedSourceCount: number) {
    // Figma Error (2635:59125): content is top-anchored at 96, retry is a solid
    // primary pill (not the outline used before the rebuild). The "检查书源"
    // secondary action is a P0 add-source flow addition.
    Scroll() {
    Column({ space: 0 }) {
      Image((this.appThemeScheme === 'night' ? $r('app.media.search_error_theme_night') : $r('app.media.search_error'))).width(80).height(80);

      Text(this.searchFailureTitle())
        .margin({ top: 20 })
        .fontFamily(TYPE_SEARCH_STATE_TITLE.fontFamily)
        .fontWeight(TYPE_SEARCH_STATE_TITLE.fontWeight)
        .fontSize(TYPE_SEARCH_STATE_TITLE.fontSizeFp)
        .lineHeight(TYPE_SEARCH_STATE_TITLE.lineHeightFp as number)
        .fontColor(readerAppColor('TOK_INK', this.appThemeScheme))
        .textAlign(TextAlign.Center);

      Text(this.searchFailureMessage())
        .margin({ top: TOK_SPACE_XS })
        .fontFamily(TYPE_APP_BODY.fontFamily)
        .fontWeight(TYPE_APP_BODY.fontWeight)
        .fontSize(TYPE_APP_BODY.fontSizeFp)
        .lineHeight(TYPE_APP_BODY.lineHeightFp as number)
        .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
        .textAlign(TextAlign.Center)
        .maxLines(2);

      Stack({ alignContent: Alignment.Center }) {
        Text('重新搜索')
          .fontFamily(TYPE_SEARCH_RETRY_ACTION.fontFamily)
          .fontWeight(TYPE_SEARCH_RETRY_ACTION.fontWeight)
          .fontSize(TYPE_SEARCH_RETRY_ACTION.fontSizeFp)
          .lineHeight(TYPE_SEARCH_RETRY_ACTION.lineHeightFp as number)
          .fontColor(readerAppColor('TOK_ON_PRIMARY', this.appThemeScheme));
      }
      .height(40)
      .margin({ top: TOK_SPACE_LG })
      .padding({ left: 28, right: 28 })
      .backgroundColor(readerAppColor('app.action.fill', this.appThemeScheme))
      .borderRadius(999)
      .onClick((): void => this.retryOperation())
      .responseRegion({ x: 0, y: -4, width: '100%', height: 48 })
      .accessibilityText('重新搜索');

      Text('检查书源')
        .fontFamily(TYPE_APP_SECONDARY_ACTION.fontFamily)
        .fontWeight(TYPE_APP_SECONDARY_ACTION.fontWeight)
        .fontSize(TYPE_APP_SECONDARY_ACTION.fontSizeFp)
        .lineHeight(TYPE_APP_SECONDARY_ACTION.lineHeightFp as number)
        .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
        .padding({ left: 18.5, right: 18.5, top: 11.5, bottom: 11.5 })
        .backgroundColor(readerAppColor('TOK_CARD_BG', this.appThemeScheme))
        .border({ width: TOK_BORDER_W, color: readerAppColor('TOK_BORDER', this.appThemeScheme) })
        .borderRadius(999)
        .margin({ top: TOK_SPACE_CONTROL_INLINE })
        .onClick((): void => this.onManageSources())
        .responseRegion({ x: 0, y: -4, width: '100%', height: 44 })
        .accessibilityText('检查书源');
    }
    .width('100%')
    .alignItems(HorizontalAlign.Center)
    .padding({ top: this.searchHeaderHeight() + 96, bottom: this.searchBottomInset(40) });
    }.width('100%').height('100%').align(Alignment.TopStart).scrollBar(BarState.Off);
  }

@Builder
  private categoryChips() {
    Scroll() {
      Row({ space: 7 }) {
        ForEach(this.kindTitles(), (label: string, index: number) => {
          Stack({ alignContent: Alignment.Center }) {
            Text(label)
              .fontFamily(TYPE_DISCOVER_CATEGORY.fontFamily)
              .fontWeight(TYPE_DISCOVER_CATEGORY.fontWeight)
              .fontSize(TYPE_DISCOVER_CATEGORY.fontSizeFp)
              .lineHeight(TYPE_DISCOVER_CATEGORY.lineHeightFp as number)
              .fontColor(this.presentation.activeKindIndex === index ? readerAppColor('TOK_ON_PRIMARY', this.appThemeScheme) : readerAppColor('app.DiscoverPage.categoryChips.fontColor.FF3F372F', this.appThemeScheme))
              .maxLines(1);
          }
          .height(32)
          .padding({ left: TOK_SPACE_SM, right: TOK_SPACE_SM })
          .backgroundColor(this.presentation.activeKindIndex === index ? readerAppColor('app.action.fill', this.appThemeScheme) : readerAppColor('app.DiscoverPage.CHIP_BG', this.appThemeScheme))
          .borderRadius(999)
          .onClick((): void => {
            this.onSelectKind(index);
          });
        }, (label: string): string => `discover-chip-${label}`);
      }
      .height(32)
      .padding({ right: TOK_SPACE_XS })
      .alignItems(VerticalAlign.Center);
    }
    .width('100%')
    .height(32)
    .scrollable(ScrollDirection.Horizontal)
    .scrollBar(BarState.Off);
  }

@Builder
  private filterRow() {
    Row({ space: 7 }) {
      Row() {
        Image((this.appThemeScheme === 'night' ? $r('app.media.discover_filter_theme_night') : $r('app.media.discover_filter'))).width(20).height(20);
        Text('筛选')
          .fontFamily(TYPE_DISCOVER_FILTER_LABEL.fontFamily)
          .fontWeight(TYPE_DISCOVER_FILTER_LABEL.fontWeight)
          .fontSize(TYPE_DISCOVER_FILTER_LABEL.fontSizeFp)
          .lineHeight(TYPE_DISCOVER_FILTER_LABEL.lineHeightFp as number)
          .fontColor(readerAppColor('app.DiscoverPage.filterRow.fontColor.FF3F372F', this.appThemeScheme))
          .maxLines(1)
          .margin({ left: 3 });
        Text(this.currentFilterText())
          .layoutWeight(1)
          .fontFamily(TYPE_DISCOVER_FILTER_VALUE.fontFamily)
          .fontWeight(TYPE_DISCOVER_FILTER_VALUE.fontWeight)
          .fontSize(TYPE_DISCOVER_FILTER_VALUE.fontSizeFp)
          .lineHeight(TYPE_DISCOVER_FILTER_VALUE.lineHeightFp as number)
          .fontColor(readerAppColor('TOK_MUTED', this.appThemeScheme))
          .textAlign(TextAlign.RIGHT)
          .maxLines(1)
          .textOverflow({ overflow: TextOverflow.Ellipsis })
          .padding({ left: 7 });
        Image((this.appThemeScheme === 'night' ? $r('app.media.discover_filter_chevron_theme_night') : $r('app.media.discover_filter_chevron'))).width(20).height(20);
      }
      .layoutWeight(1)
      .height(34)
      .padding({ left: TOK_SPACE_CONTROL_INLINE, right: 5 })
      .alignItems(VerticalAlign.Center)
      .backgroundColor(readerAppColor('TOK_CARD_BG', this.appThemeScheme))
      .border({ width: TOK_BORDER_W, color: readerAppColor('app.DiscoverPage.FILTER_BORDER', this.appThemeScheme) })
      .borderRadius(8);

      Row() {
        Image($r('app.media.discover_apply')).width(20).height(20);
        Text('应用')
